/// <summary>
 ///  Finds NDXItemHK2MGKValues record
/// </summary>
/// <param name = "_inventTableRefRecId">RecId Of invent table record</param>
/// <param name = "_forUpdate">for update</param>
 /// <returns>NDXItemHK2MGKValues record</returns>
 public static NDXItemHK2MGKValues find(RefRecId _inventTableRefRecId, boolean _forUpdate = false)
 {
     NDXItemHK2MGKValues lNDXItemHK2MGKValues;

     lNDXItemHK2MGKValues.selectForUpdate(_forUpdate);

     if(_inventTableRefRecId)
     {
         select firstonly lNDXItemHK2MGKValues
             where lNDXItemHK2MGKValues.InventTableRefRecId == _inventTableRefRecId;
     }

     return lNDXItemHK2MGKValues;
 }

/// <summary>
/// find or creates record
/// </summary>
/// <param name = "_itemId">itemid</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDXItemHK2MGKValues record</returns>
public static NDXItemHK2MGKValues findOrCreate(ItemId _itemId, boolean _forUpdate = false)
{
    NDXItemHK2MGKValues lNDXItemHK2MGKValues;
    InventTable lInventTable = InventTable::find(_itemId);

    if(lInventTable)
    {
        lNDXItemHK2MGKValues = NDXItemHK2MGKValues::find(lInventTable.RecId, _forUpdate);

        if(!lNDXItemHK2MGKValues)
        {
            lNDXItemHK2MGKValues.InventTableRefRecId = lInventTable.RecId;
            lNDXItemHK2MGKValues.insert();
        }
    }
    return lNDXItemHK2MGKValues;
}

/// <summary>
/// find or creates record
/// </summary>
/// <param name = "_inventTableRecId">RecId of invent table record</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDXItemHK2MGKValues record</returns>
public static NDXItemHK2MGKValues findOrCreateByInvenTableRecId(RecId _inventTableRecId, boolean _forUpdate = false)
{
    NDXItemHK2MGKValues lNDXItemHK2MGKValues;

    if(_inventTableRecId)
    {
        lNDXItemHK2MGKValues = NDXItemHK2MGKValues::find(_inventTableRecId, _forUpdate);

        if(!lNDXItemHK2MGKValues)
        {
            lNDXItemHK2MGKValues.InventTableRefRecId = _inventTableRecId;
            lNDXItemHK2MGKValues.insert();
        }
    }
    return lNDXItemHK2MGKValues;
}

/// <summary>
/// Displays current HK2 Group id
/// </summary>
/// <returns>HK2 group</returns>
[SysClientCacheDataMethodAttribute(true)]
display KCS_HK2GroupId dispCurrentHK2Group()
{
    InventTable lInventTable = InventTable::findByRecId(this.InventTableRefRecId);

    KCS_HK2FactorGroup lKCS_HK2FactorGroup = KCS_HK2FactorGroup::findByRecId(lInventTable.NDXHK2GroupRefRecId);

    return lKCS_HK2FactorGroup ? lKCS_HK2FactorGroup.HK2GroupId : '';
}

/// <summary>
/// Displays current MGK Group id
/// </summary>
/// <returns>MGK Group</returns>
[SysClientCacheDataMethodAttribute(true)]
display AVAMGKGroup dispCurrentMGKGroup()
{
    InventTable lInventTable;
    InventTableModule lInventTableModule;
    AVAMGKFactors lAVAMGKFactors;

    select firstonly lAVAMGKFactors
        join lInventTableModule
            where lInventTableModule.NDXMGKGroupRefRecId == lAVAMGKFactors.RecId
        join lInventTable
            where lInventTable.ItemId == lInventTableModule.ItemId
            && lInventTable.RecId == this.InventTableRefRecId
        && lInventTableModule.ModuleType == ModuleInventPurchSales::Invent;


    return lAVAMGKFactors ? lAVAMGKFactors.MGKGroup : '';
}

