public boolean validateWrite()
{
    boolean ret;
    ret = super();
    return ret;
}

 /// <summary>
/// Display MGK/HK2 price (HK1 * HK2Factor * MGKFactor)
/// </summary>
/// <returns>MGK/HK2 Price</returns>
[SysClientCacheDataMethodAttribute(true)]
display NDXNewMGKPrice dispNewMGK()
{
    InventItemGroupItem lInventItemGroupItem = InventItemGroupItem::findByItemIdLegalEntity(InventTable::findByRecId(this.InventTableRefRecId).ItemId);
    AVAMGKFactors factor = AVAMGKFactors::findByRecId(this.MGKGroupNewRefRecId);

    return lInventItemGroupItem.dispHK1current() * (factor && factor.MGKFactor ? factor.MGKFactor : 1);
}

/// <summary>
/// Display MGK/HK2 price (HK1 * HK2Factor * MGKFactor)
/// </summary>
/// <returns>MGK/HK2 Price</returns>
[SysClientCacheDataMethodAttribute(true)]
display NDXNewHK2MGKPrice dispNewHK2MGK()
{

    InventItemGroupItem lInventItemGroupItem = InventItemGroupItem::findByItemIdLegalEntity(InventTable::findByRecId(this.InventTableRefRecId).ItemId);
    AVAMGKFactors factor = AVAMGKFactors::findByRecId(this.MGKGroupNewRefRecId);
    KCS_HK2FactorGroup  hk2FactorGroup  = KCS_HK2FactorGroup::findByRecId(this.HK2GroupNewRefRecId);

    return lInventItemGroupItem.dispHK1current() * (factor && factor.MGKFactor ? factor.MGKFactor : 1) * (hk2FactorGroup && hk2FactorGroup.HK2Factor ? hk2FactorGroup.HK2Factor : 1);
}

public void update()
{
    InventTable lInventTable = InventTable::findByRecId(this.InventTableRefRecId);
    InventTableModule lInventTableModule = InventTableModule::find(lInventTable.ItemId, ModuleInventPurchSales::Invent, true);
    this.Active = NoYes::No;

    if((this.HK2GroupNewRefRecId != 0 && this.HK2GroupNewRefRecId != lInventTable .NDXHK2GroupRefRecId)
    || (this.MGKGroupNewRefRecId != 0 && this.MGKGroupNewRefRecId != lInventTableModule.NDXMGKGroupRefRecId))
    {
        this.Active = NoYes::Yes;
    }

    super();
}
